# Gencor operating history from filed 10-K selected data / income statements (USD thousands)
rev={2000:96808,2001:71134,2002:67485,2003:55898,2004:54070,2005:48140,2006:67107,2007:75286,2008:88343,2009:56789,2010:55587,2011:59692,2012:63182,2013:48943,2014:40017,2015:39230,2016:69991,2017:80608,2018:98614,2019:81329,2020:77420,2021:85278,2022:103479,2023:105075,2024:113166,2025:115437}
op={2000:3848,2001:-3870,2002:2059,2003:-1173,2004:4171,2005:-1258,2006:1359,2007:6333,2008:6848,2009:-4769,2010:-3049,2011:-1743,2012:393,2013:2578,2014:-26,2015:-794,2016:7816,2017:10236,2018:13715,2019:9470,2020:5536,2021:701,2022:4167,2023:13425,2024:13687,2025:14018}
print('Gencor op margin by FY:'); print(' '.join('%d:%.1f%%'%(y,100*op[y]/rev[y]) for y in sorted(rev)))
def agg(a,b): 
    ys=[y for y in rev if a<=y<=b]; return 100*sum(op[y] for y in ys)/sum(rev[y] for y in ys), sum(1 for y in ys if op[y]<=0), len(ys)
for a,b in [(2000,2025),(2009,2025),(2010,2025),(2009,2015),(2016,2025),(2021,2025)]:
    print('GENC %d-%d aggregate op margin %.1f%%, loss years %d of %d'%((a,b)+agg(a,b)))
# Astec calendar years from XBRL companyfacts (USD millions)
arev={2008:973.7,2009:738.1,2010:737.1,2011:908.6,2012:936.3,2013:933.0,2014:975.6,2015:983.2,2016:1147.4,2017:1184.7,2018:1171.6,2019:1169.6,2020:1024.4,2021:1095.5,2022:1274.5,2023:1338.2,2024:1305.1,2025:1410.4}
aop={2008:91.8,2009:9.9,2010:49.2,2011:58.4,2012:51.1,2013:55.7,2014:51.7,2015:50.0,2016:87.2,2017:55.5,2018:-86.4,2019:25.1,2020:40.5,2021:19.9,2022:7.5,2023:48.6,2024:23.2,2025:65.9}
print('Astec op margin:',' '.join('%d:%.1f%%'%(y,100*aop[y]/arev[y]) for y in sorted(arev)))
for a,b in [(2009,2025),(2010,2025),(2009,2015),(2016,2025),(2021,2025)]:
    ys=[y for y in arev if a<=y<=b]
    print('ASTE %d-%d aggregate op margin %.1f%%, loss years %d of %d'%(a,b,100*sum(aop[y] for y in ys)/sum(arev[y] for y in ys),sum(1 for y in ys if aop[y]<=0),len(ys)))
